class Refused(Exception):
    """The model declined."""


class CutOff(Exception):
    """The reply hit max_tokens."""


class Exhausted(Exception):
    """Every attempt failed validation."""


def parse_with_retry(call, messages, check, max_attempts=3):
    """Call the model until check(reply) returns no errors.

    call(messages) returns (reply, stop) where stop is "end", "refusal" or "max_tokens".
    check(reply) returns (record, errors), errors being a list of strings.
    Return (record, attempt). A refusal raises Refused and a cut-off reply raises CutOff at once;
    a failed reply goes back to the model with its errors; after max_attempts, raise Exhausted.
    The caller's messages list is not modified.
    """
    messages = list(messages)
    for attempt in range(1, max_attempts + 1):
        reply, stop = call(messages)
        if stop == "refusal":
            raise Refused(reply)
        if stop == "max_tokens":
            raise CutOff(reply)
        record, errors = check(reply)
        if not errors:
            return record, attempt
        messages += [
            {"role": "assistant", "content": reply},
            {"role": "user", "content": "That reply did not validate: "
             + "; ".join(errors) + ". Return the corrected JSON object only."},
        ]
    raise Exhausted(errors)
